<!-- This file is generated by AI. -->

<!--
  语句配音配置面板 (配音卡操作台左侧)。

  * 参数编辑**永不禁用**: 一旦改动参数, 该配置即为"新配置", 不影响既有历史记录;
  * 「测试」入立即队列 (x4), 「生成」入普通队列 (x32);
  * 「应用」把选中历史项的音频落盘并改写 `-vocal=`；
  * 「移除」只清除当前语句的 `-vocal=` (不删文件、不清历史);
  * 语音之外的参数 (文本) 随场景内容变化, 不随历史项回填。

  数值参数一律走 `NumberInput` (数字框, **不是滑杆**)。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import type { Character, SayLine } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { formatDuration } from '../voice/estimate';
  import {
    GENERATE_SAMPLE_STEPS,
    LANGUAGE_CODES,
    LANGUAGE_LABELS,
    PARAM_TICKS,
    TEST_SAMPLE_STEPS,
    historyForLine,
    preferredReference,
    randomSeed,
    type HistoryEntry,
    type VoiceParams,
  } from '../voice/types';
  import Button from './Button.svelte';
  import Icon from './Icon.svelte';
  import NumberInput from './NumberInput.svelte';
  import Select from './Select.svelte';
  import VoiceReferenceDialog from './VoiceReferenceDialog.svelte';

  let {
    cardId,
    dialogue,
    characters,
  }: {
    cardId: string;
    dialogue: SayLine;
    characters: Character[];
  } = $props();

  /**
   * 用户改过的参数 (null = 还没动过, 显示控制器的推导值)。
   *
   * 控制器推出来的那一份**始终是底** (`derivedParams`): 只把"用户改了什么"记成局部叠加,
   * 于是不会出现"某次读得太早拿到 null, 面板就永远空着"。
   */
  let edited = $state<VoiceParams | null>(null);
  let advancedOpen = $state(false);
  let pickerOpen = $state(false);
  let busy = $state(false);
  let message = $state<string | null>(null);

  /** 本卡: 从 store 读, 而不是 `voiceController.getCard()`。 */
  const card = $derived(appStore.sceneVoiceEditors.get(cardId) ?? null);

  /*
   * ⚠️ **每个"这一句的历史 / 参数"相关的派生都要读一次 `appStore.voiceTick`。**
   *
   * 控制器是**就地**改状态的 (`card.history` 换成新数组、`entry.status` 直接改字段), 而 store 里
   * 那个 `card` 对象的引用始终不变; 入队 / 任务推进只调 `emit()` → `setVoiceTick()`。
   *
   * `$derived` 用 `===` 比较新旧值, 值不变就不向下游传播 —— 因此把令牌读在中间层 (`card`) 上是
   * 不够的: `card` 重算后仍是同一个对象, 下游会被判定为"依赖没变"而永远用缓存值。令牌必须读在
   * **真正产出新值的叶子派生**上 (字符串 / 新数组 / 浅拷贝), "点生成后立刻出现任务卡"才生效。
   */
  /**
   * 当前选中的记录。
   *
   * `selectedHistoryId` 是**整张卡**共用的选中项: 切换语句后它还指着上一句的记录。必须按
   * 当前语句过滤, 否则换了对话者仍会沿用上一句的角色与参数 (自动识别失效)。
   *
   * 返回**浅拷贝**而不是原对象: 任务状态 / 耗时是在原对象上就地改的, 直接返回它会让
   * 下游 (`running` / `canApply` / 状态行) 永远看到同一份缓存。`params` 是不可变快照,
   * 共享引用即可。
   */
  const selected = $derived.by<HistoryEntry | null>(() => {
    void appStore.voiceTick;
    const id = card?.selectedHistoryId ?? null;
    const entry = historyForLine(card?.history.find((item) => item.id === id) ?? null, dialogue.line);
    return entry ? { ...entry } : null;
  });
  const selectedId = $derived(selected?.id ?? null);
  const matchHint = $derived.by(() => {
    void appStore.voiceTick;
    return describeMatch(card?.matches.get(dialogue.line)?.reason);
  });

  /**
   * 参数来源键: 语句身份 + 选中的历史项。
   *
   * 这两者任一变化都要**重新取一遍参数**: 参数是本地状态, 不重建就表现为"点别的记录时面板
   * 纹丝不动"。
   *
   * 刻意**不把刷新令牌算进来**: 队列里任何一条任务完成、任何一次列表清理都会让它 +1,
   * 跟着重建就会把用户刚调好、还没生成的那套参数盖回默认值。
   *
   * 而 `patch` 自己会清空选中项, 那一次也不能重建 (同样会盖掉用户刚调的参数), 因此它也把这个
   * 键一并标成"已同步"。
   */
  function sourceKeyOf(selection: string | null): string {
    return `${dialogue.line}\u001f${dialogue.hash}\u001f${selection ?? ''}`;
  }

  /**
   * 已同步的来源键。
   *
   * **刻意不是 `$state`**: 它只是一个"这次变化我已经处理过了"的标记, 不该参与响应式依赖。
   */
  let syncedSource: string | null = null;

  $effect(() => {
    const key = sourceKeyOf(selectedId);
    if (syncedSource === key) return;
    syncedSource = key;
    // 换了语句或换了选中的记录 -> 丢弃本地的叠加, 回到控制器推导出来的那一套
    edited = null;
    message = null;
  });

  /** 控制器按"当前选中历史 + 角色归属 + 默认值"推导出来的参数 */
  const derivedParams = $derived.by<VoiceParams | null>(() => {
    void appStore.voiceTick;
    // `currentParams` 每次都新建一个对象, 因此这一层的值在令牌变化时必然不同 -> 会传播
    return voiceController.currentParams(cardId, dialogue);
  });
  const params = $derived<VoiceParams | null>(edited ?? derivedParams);

  const character = $derived.by(() => {
    void characters;
    return voiceController.characterById(params?.characterId ?? null);
  });

  /*
   * 参考音频选择框只对**当前这个角色**有意义。
   *
   * 角色一旦变化 (换人、或被删除后重新选一个), 就把打开状态收掉: 否则会出现
   * "对话框因为角色为空而没渲染, 但状态还挂着", 等角色一填上就自己弹出来。
   */
  let lastCharacterId: string | null = null;
  $effect(() => {
    const id = params?.characterId ?? null;
    if (id === lastCharacterId) return;
    lastCharacterId = id;
    pickerOpen = false;
  });

  const isNewConfiguration = $derived.by(() => {
    void appStore.voiceTick;
    if (!params) return false;
    return voiceController.isNewConfiguration(cardId, params);
  });
  const canApply = $derived(
    Boolean(selected && selected.status === 'done' && selected.audioHash && !isNewConfiguration)
  );
  const running = $derived(selected?.status === 'pending' || selected?.status === 'running');
  const hasVocal = $derived(Boolean(dialogue.vocal));

  /** 高级设置这一行的默认值 (工作台的默认配置) */
  const advancedDefaults = $derived(voiceController.getSettings().defaults);
  const resetHint = $derived(
    `恢复高级设置的默认值（topK ${advancedDefaults.topK} · topP ${advancedDefaults.topP}` +
      ` · 重复惩罚 ${advancedDefaults.repetitionPenalty} · 采样步数 x${advancedDefaults.generateSampleSteps}）`
  );

  function update(patch: Partial<VoiceParams>): void {
    const current = params;
    if (!current) return;
    edited = { ...current, ...patch };
    // 参数一改, 视为新配置 -> 取消历史选中 (应用按钮随之禁用)
    message = null;
    voiceController.selectHistory(cardId, null);
    // 这次清空是"改参数"引起的, 不是用户选了别的记录 -> 不要重建
    syncedSource = sourceKeyOf(null);
  }

  function resetAdvanced(): void {
    update({
      topK: advancedDefaults.topK,
      topP: advancedDefaults.topP,
      repetitionPenalty: advancedDefaults.repetitionPenalty,
      sampleSteps: advancedDefaults.generateSampleSteps,
    });
  }

  function openReferencePicker(): void {
    if (!character) {
      message = '请先选择角色，再挑选参考音频';
      return;
    }
    pickerOpen = true;
  }

  function enqueue(kind: 'test' | 'generate'): void {
    const current = params;
    if (!current) return;
    if (!character || character.references.length === 0) {
      message = '请先为角色添加参考音频';
      return;
    }
    const reference = preferredReference(character, current.referenceHash);
    if (!reference) {
      message = '请先为角色添加参考音频';
      return;
    }
    const task = voiceController.enqueue(cardId, kind, dialogue, { ...current, referenceHash: reference.hash });
    if (task) {
      message =
        kind === 'test'
          ? `已加入优先队列（测试 x${task.params.sampleSteps}）`
          : `已加入常规队列（生成 x${task.params.sampleSteps}）`;
    } else {
      message = '入队失败：找不到当前场景卡，请重新打开配音卡';
    }
  }

  async function apply(): Promise<void> {
    const current = selected;
    if (!current) return;
    busy = true;
    try {
      await voiceController.apply(cardId, current.id);
      message = '已应用并更新 -vocal=';
    } catch (error) {
      message = String(error);
    } finally {
      busy = false;
    }
  }

  async function remove(): Promise<void> {
    busy = true;
    try {
      await voiceController.remove(cardId);
      message = '已移除本句配音引用';
    } catch (error) {
      message = String(error);
    } finally {
      busy = false;
    }
  }

  /**
   * 从操作台取消正在跑的这一条。
   *
   * 取消后这条记录会从历史里移除 (任务队列里仍看得到), 因此这里要**主动把参数源标成
   * "已同步"** —— 否则选中项一变, 面板会重新取一遍默认参数, 用户刚调好的那套配置就被
   * 冲掉了。取消的是这次生成, 不是这套配置。
   */
  function cancel(): void {
    const current = selected;
    if (!current) return;
    voiceController.cancel(current.id);
    syncedSource = sourceKeyOf(null);
    message = '已取消这一条（记录已从本句历史移除，队列里仍可见）';
  }
  /*
   * 状态行**永远有文字**, 且排在按钮上方。
   *
   * 两件事都是刻意的: 空行既占位又看不出当前是什么状态; 而"新配置/已生成"这类信息
   * 贴在按钮下面时, 读起来像按钮的补充说明 —— 放到上面才能和下面的参数区连成一句。
   */
  const stepLabel = $derived(
    selected ? `${selected.kind === 'test' ? '测试' : '生成'} x${selected.params.sampleSteps}` : ''
  );
  const statusText = $derived(
    running
      ? selected?.status === 'pending'
        ? `已加入队列，等待执行（${stepLabel}）`
        : `正在生成（${stepLabel}）…`
      : isNewConfiguration
        ? '当前为新配置，尚未生成'
        : selected?.status === 'failed'
          ? '这次生成失败了，点开右侧记录可以看完整报错'
          : selected
            ? `当前配置已生成（${stepLabel}${selected.elapsed !== undefined ? ` · 响应 ${formatDuration(selected.elapsed)}` : ''}）`
            : '当前配置与历史记录一致，可直接应用'
  );
  const statusTone = $derived(
    running ? 'run' : isNewConfiguration ? 'new' : selected?.status === 'failed' ? 'fail' : 'ok'
  );

  const characterOptions = $derived(
    characters.map((item) => ({
      value: item.id,
      label: `${item.name}${item.references.length === 0 ? '（无参考音频）' : ''}`,
    }))
  );

  const languageOptions = $derived(
    LANGUAGE_CODES.map((code) => ({ value: code, label: LANGUAGE_LABELS[code] ?? code }))
  );

  /** 取值范围 (显示在字段标签右侧; 输入框留给数值本身和步进器) */
  function range(tick: { min: number; max: number }): string {
    return `${tick.min}~${tick.max}`;
  }

  /** 参考音频下拉的显示文案 */
  function referenceLabel(): string {
    if (!character) return '未选择角色';
    if (character.references.length === 0) return '该角色暂无参考音频';
    const reference = preferredReference(character, params?.referenceHash);
    if (!reference) return '该角色暂无参考音频';
    const preview = reference.text.length > 14 ? `${reference.text.slice(0, 14)}…` : reference.text;
    return `${reference.starred ? '★ ' : ''}${preview}（${reference.duration.toFixed(1)}s）`;
  }

  function describeMatch(reason: string | undefined): string {
    switch (reason) {
      case 'figureId':
        return '按立绘匹配';
      case 'name':
        return '按名称匹配';
      case 'namePartial':
        return '按名称包含匹配';
      case 'narration':
        return '继承旁白';
      default:
        return '';
    }
  }
</script>

<div class="voice-sentence-panel">
  {#if params}
    <!--
      设置项独立滚动, 页脚固定: 面板高度是写死的 (见 `.scene-voice-panel`), 展开
      「高级设置」时只有上面这一段滚, 状态行与按钮不会跟着上下跳。
    -->
    <div class="voice-fields">
      <!-- 第一行: 角色 / 语言 / 参考音频。参考音频要看清文本与时长, 因此由它占满剩余宽度。 -->
      <div class="voice-row">
        <label class="voice-field voice-field-character">
          <span class="voice-label">角色</span>
          <Select
            value={params.characterId ?? ''}
            title={character ? `${character.name}${matchHint && !selected ? `（${matchHint}）` : ''}` : '未选择角色'}
            placeholder="未选择"
            options={characterOptions}
            onchange={(value) => {
              const id = value || null;
              const next = voiceController.characterById(id);
              /*
               * 换角色时**同时**做两件事, 顺序不能颠倒:
               *   1. 把新的角色归属写回 store (`assignCharacter`) —— 这是"整个场景里该说话者
               *      由谁配"的持久决定, 不写的话下次打开这一行又回到旧角色;
               *   2. 本地参数跟着换, 且清掉参考音频 (旧角色的 hash 在新角色下必然无效)。
               */
              if (dialogue.speaker !== null) {
                voiceController.assignCharacter(card?.scenePath ?? cardId, dialogue.speaker, id);
              }
              update({ characterId: id, referenceHash: preferredReference(next)?.hash ?? null });
            }}
          />
        </label>

        <label class="voice-field voice-field-language">
          <span class="voice-label">语言</span>
          <Select
            value={params.language}
            title="本条对话的合成语言"
            options={languageOptions}
            onchange={(language) => update({ language })}
          />
        </label>

        <label class="voice-field voice-field-reference">
          <span class="voice-label">参考音频</span>
          <!--
            参考音频用下拉直接选, 但点开即弹出选择对话框 (带搜索与试听) —— 参考音频
            **需要看时长与文本**才能选, 普通下拉的选项里放不下这些信息。

            外观必须与同一行另外两个下拉**完全一致** (字号 / 内边距 / 箭头位置与大小): 箭头因此
            绝对定位贴进框内右侧, 字号与 `.select-trigger` 对齐; 改成"`ui-input` + 兄弟节点箭头"
            就会在同一行里字号更大、箭头飘到框外面。

            **没有角色时不打开**: 参考音频是角色的东西, 那时弹出来只会是个空壳。
          -->
          <div class="voice-reference-trigger">
            <!--
              这个控件的真实语义是"点开一个**对话框**", 因此用 `aria-haspopup="dialog"` +
              `aria-expanded`; 这里**不写** `role="combobox"` —— 那个角色要求 `aria-controls`
              指向一个真实存在的元素, 而对话框是按需挂载的。可见名称由外层 `<label>` 的
              「参考音频」给出, `aria-label` 只是把它写实; `title` 负责当前值 / "请先选择角色"。
            -->
            <input
              class="ui-input"
              value={referenceLabel()}
              readonly
              title={character ? referenceLabel() : '请先在左侧选择角色，再挑选参考音频'}
              aria-label="参考音频"
              aria-haspopup="dialog"
              aria-expanded={pickerOpen}
              onclick={openReferencePicker}
              onkeydown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  openReferencePicker();
                }
              }}
            />
            <span class="select-chevron" aria-hidden="true"><Icon name="ChevronDown" size={14} /></span>
          </div>
        </label>
      </div>

      <!-- 第二行: 文本 (独占一行; 它是唯一可能很长的输入) -->
      <label class="voice-field voice-field-text">
        <span class="voice-label">文本</span>
        <textarea
          class="ui-input voice-control voice-text"
          rows="2"
          value={params.text}
          oninput={(event) => update({ text: event.currentTarget.value })}></textarea>
      </label>

      <!-- 第三行: 种子 / 温度 / 语速 / 高级设置 -->
      <div class="voice-row">
        <label class="voice-field voice-field-seed">
          <span class="voice-label">种子</span>
          <div class="voice-seed">
            <NumberInput value={params.seed} tick={PARAM_TICKS.seed} integer oncommit={(seed) => update({ seed })} />
            <Button
              appearance="bare"
              icon="ArrowSync"
              title="换一个随机种子"
              onclick={() => update({ seed: randomSeed() })}
            />
          </div>
        </label>

        <label class="voice-field voice-field-number">
          <span class="voice-label">
            温度
            <span class="voice-label-range">{range(PARAM_TICKS.temperature)}</span>
          </span>
          <NumberInput
            value={params.temperature}
            tick={PARAM_TICKS.temperature}
            oncommit={(temperature) => update({ temperature })}
          />
        </label>

        <label class="voice-field voice-field-number">
          <span class="voice-label">
            语速
            <span class="voice-label-range">{range(PARAM_TICKS.speedFactor)}</span>
          </span>
          <NumberInput
            value={params.speedFactor}
            tick={PARAM_TICKS.speedFactor}
            oncommit={(speedFactor) => update({ speedFactor })}
          />
        </label>

        <!-- 高级设置的开关跟在语速右边: 二者相关, 同一行也更紧凑 -->
        <div class="voice-field voice-field-advanced">
          <span class="voice-label">&nbsp;</span>
          <Button appearance="bare" icon="Settings" onclick={() => (advancedOpen = !advancedOpen)}>
            高级设置 {advancedOpen ? '▴' : '▾'}
          </Button>
        </div>
      </div>

      <!-- 高级设置收成一行: 面板高度写死, 参数一多行就会把按钮挤出视野 -->
      {#if advancedOpen}
        <div class="voice-advanced-body">
          <div class="voice-row">
            <label class="voice-field voice-field-number">
              <span class="voice-label">
                topK
                <span class="voice-label-range">{range(PARAM_TICKS.topK)}</span>
              </span>
              <NumberInput value={params.topK} tick={PARAM_TICKS.topK} integer oncommit={(topK) => update({ topK })} />
            </label>

            <label class="voice-field voice-field-number">
              <span class="voice-label">
                topP
                <span class="voice-label-range">{range(PARAM_TICKS.topP)}</span>
              </span>
              <NumberInput value={params.topP} tick={PARAM_TICKS.topP} oncommit={(topP) => update({ topP })} />
            </label>

            <label class="voice-field voice-field-number">
              <span class="voice-label">
                重复惩罚
                <span class="voice-label-range">{range(PARAM_TICKS.repetitionPenalty)}</span>
              </span>
              <NumberInput
                value={params.repetitionPenalty}
                tick={PARAM_TICKS.repetitionPenalty}
                oncommit={(repetitionPenalty) => update({ repetitionPenalty })}
              />
            </label>

            <label class="voice-field voice-field-number">
              <span class="voice-label">采样步数</span>
              <Select
                value={String(params.sampleSteps)}
                title="正式生成使用的采样步数"
                options={[4, 8, 16, 32].map((steps) => ({ value: String(steps), label: `x${steps}` }))}
                onchange={(value) => update({ sampleSteps: Number.parseInt(value, 10) || GENERATE_SAMPLE_STEPS })}
              />
            </label>

            <!--
              「恢复默认」跟在最后一项右边: 高级设置里的四项都是"调过之后容易忘了原值"的
              参数, 与其让人回想默认是多少, 不如给一个按钮。作用范围**就是这一行**,
              温度与语速不受影响 (它们在上一行, 不属于高级设置)。
            -->
            <div class="voice-field voice-field-reset">
              <span class="voice-label">&nbsp;</span>
              <Button appearance="bare" icon="ArrowReset" title={resetHint} onclick={resetAdvanced}>恢复默认</Button>
            </div>
          </div>
        </div>
      {/if}
    </div>

    <!--
      状态行与按钮同属一块页脚: 与上面的参数区用一条分隔线隔开, 状态行紧贴按钮上方。
    -->
    <div class="voice-footer">
      <div class="voice-status-line">
        <span class="voice-status-{statusTone}">{statusText}</span>
        {#if message}
          <span class="voice-message">{message}</span>
        {/if}
      </div>

      <div class="voice-actions">
        <Button icon="Flash" disabled={busy} onclick={() => enqueue('test')}>
          测试 x{TEST_SAMPLE_STEPS}
        </Button>
        <Button appearance="primary" icon="MicRecord" disabled={busy} onclick={() => enqueue('generate')}>
          生成 x{params.sampleSteps}
        </Button>
        <span class="voice-actions-spacer"></span>
        {#if running}
          <!-- 取消 = 撤下这一条, 用叉; 「移除」才是"从脚本里拿掉", 仍用垃圾桶 -->
          <Button icon="Dismiss" title="取消（推理无法中断，返回后丢弃结果）" onclick={cancel}>取消</Button>
        {:else}
          <Button
            icon="Delete"
            title="清除当前语句的 -vocal=（不删除音频与历史）"
            disabled={!hasVocal || busy}
            onclick={() => void remove()}
          >
            移除
          </Button>
        {/if}
        <Button appearance="primary" icon="Checkmark" disabled={!canApply || busy} onclick={() => void apply()}>
          应用
        </Button>
      </div>
    </div>
  {/if}

  <!--
    参考音频选择对话框: 加完一条就把它当成当前参考音频, 但**不关闭**这个对话框
    (补语料通常是连着加几条) —— 见 `VoiceReferenceDialog` 的 `onAdded`。
  -->
  <VoiceReferenceDialog
    open={pickerOpen}
    {character}
    selectedHash={params?.referenceHash ?? null}
    onPick={(hash) => {
      update({ referenceHash: hash });
      pickerOpen = false;
    }}
    onAdded={(hash) => update({ referenceHash: hash })}
    onClose={() => (pickerOpen = false)}
    onCharactersChanged={() => {
      // 角色库变了, 面板上的候选与参考音频随之刷新 (store 由控制器同步)
    }}
  />
</div>
